def node(i,t,label,x,y,sub='',tag='documentado',w=230,h=76):return {'id':i,'type':t,'label':label,'sublabel':sub,'tag':tag,'pos':[x,y],'size':[w,h]}
def edge(a,b,label='',variant='default',**kw):
    d={'id':a+'-'+b,'from':a,'to':b,'variant':variant}
    if label:d['label']=label
    return dict(d,**kw)
def card(title,*items,dot='cyan'):return {'dot':dot,'title':title,'items':list(items)}
def save(slug,title,d,desc,refs,members=None):
    p=OUT/slug;p.mkdir(exist_ok=True)
    (p/'candidate.json').write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
    diagrams.append({'slug':slug,'title':title,'type':d['diagram_type'],'description':desc,'refs':refs,'members':members or []})

